// ─── EvaluationTab.tsx ───────────────────────────────────────────────────────
// Evaluation tab — hook + common table compose மட்டும்
// No API calls here. No spinner. Skeleton rows show on mount.

import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import styles from "./EvaluationTab.module.scss";
import EvaluationTable from "../../components/EvaluationTable/EvaluationTable";
import { useEvaluationData } from "../../hooks/useEvaluationData";

interface EvaluationTabProps {
  currentUserEmail: string;   // RecrutimentApp props.CurrentUserEmailId
  employeeList: any[];         // RecrutimentApp props.EmployeeList
}

const EvaluationTab: React.FC<EvaluationTabProps> = ({
  currentUserEmail,
  employeeList,
}) => {
  const navigate = useNavigate();

  // All data fetching via hook
  const { rows, tooltipData, fetchData, fetchTooltip, checkScoreSheet } =
    useEvaluationData(currentUserEmail, employeeList);

  // Inline alert state (no modal)
  const [alert, setAlert] = useState<{ msg: string; type: string } | null>(null);

  // Fetch on mount (Selection Process click → tab mounts → data loads)
  useEffect(() => {
    void fetchData();
  }, [fetchData]);

  return (
    <div className={styles.card}>

      {/* ── Inline alert banner ── */}
      {alert && (
        <div className={`${styles.alert} ${styles[alert.type] ?? ""}`}>
          <span>{alert.msg}</span>
          <button className={styles.alertClose} onClick={() => setAlert(null)}>✕</button>
        </div>
      )}

      {/* ── Card header ── */}
      <div className={styles.header}>
        <h2 className={styles.title}>Candidate Evaluations</h2>
        <button className={styles.backBtn} onClick={() => navigate("/Dashboard")}>
          ↺ BACK TO DASHBOARD
        </button>
      </div>

      {/* ── Common table component ── */}
      <EvaluationTable
        rows={rows}
        tooltipData={tooltipData}
        onHover={fetchTooltip}
        onEvaluate={(row) => checkScoreSheet(row.id, row.statusId)}
        onShowAlert={(msg, type) => setAlert({ msg, type })}
      />
    </div>
  );
};

export default EvaluationTab;
